begin;
create temp table chat_test_ids(label text primary key,id uuid not null);
insert into chat_test_ids select label,gen_random_uuid() from unnest(array['alice','bob','outsider']) label;
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data)
select id,label||'-'||id||'@example.invalid',now(),jsonb_build_object('full_name',label,'company_name','Chat test '||label) from chat_test_ids;
update public.profiles set company_id=(select company_id from public.profiles where id=(select id from chat_test_ids where label='alice')),role=case when id=(select id from chat_test_ids where label='bob') then 'employee' when id=(select id from chat_test_ids where label='cara') then 'manager' else 'hr_admin' end where id in(select id from chat_test_ids where label not in('alice','outsider'));
update public.profiles set active=false where id=(select id from chat_test_ids where label='inactive');
grant select,insert on chat_test_ids to authenticated;
create temp table chat_test_results(test text,passed boolean);
grant select,insert on chat_test_results to authenticated;
create function pg_temp.chat_assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is not true then raise exception 'TEST FAILED: %',label;end if;insert into chat_test_results values(label,true);end$$;
create function pg_temp.chat_denied(statement text,label text) returns void language plpgsql as $$declare denied boolean:=false;begin begin execute statement;exception when others then denied:=true;end;perform pg_temp.chat_assert(denied,label);end$$;
insert into public.ai_company_limits(company_id,plan,enabled)select company_id,'enterprise',true from public.profiles where id=(select id from chat_test_ids where label='alice')on conflict(company_id)do update set plan='enterprise';
select set_config('request.jwt.claim.sub',(select id::text from chat_test_ids where label='alice'),true);
set local role authenticated;
insert into chat_test_ids values('group',public.chat_create('group','Attachment QA',(select array[id]from chat_test_ids where label='bob')));
reset role;
insert into public.chat_messages(id,conversation_id,company_id,sender_id,body,created_at)
select gen_random_uuid(),g.id,p.company_id,p.id,'Fictional message '||n,now()-interval '2 days'+n*interval '1 minute' from generate_series(1,120)n cross join chat_test_ids g join public.profiles p on p.id=(select id from chat_test_ids where label='alice')where g.label='group';
insert into chat_test_ids select 'anchor',id from public.chat_messages where conversation_id=(select id from chat_test_ids where label='group')and body='Fictional message 60';
set local role authenticated;
do $$declare page jsonb;after_page jsonb;before_page jsonb;begin
page:=public.chat_detail((select id from chat_test_ids where label='group'),null,(select id from chat_test_ids where label='anchor'));
perform pg_temp.chat_assert(jsonb_array_length(page->'messages')=50,'anchor loads surrounding messages');
perform pg_temp.chat_assert(page->'messages'->0->>'body'='Fictional message 36','24 messages before quote');
perform pg_temp.chat_assert(page->'messages'->49->>'body'='Fictional message 85','25 messages after quote');
perform pg_temp.chat_assert((page->>'has_newer')::boolean and(page->>'has_older')::boolean,'both paging directions available');
after_page:=public.chat_after((select id from chat_test_ids where label='group'),(page->'messages'->49->>'seq')::bigint);
perform pg_temp.chat_assert(jsonb_array_length(after_page->'messages')=35 and after_page->'messages'->0->>'body'='Fictional message 86','continue forward without a gap');
perform pg_temp.chat_assert(not(after_page->>'has_newer')::boolean,'reaches newest message');
before_page:=public.chat_detail((select id from chat_test_ids where label='group'),(page->'messages'->0->>'seq')::bigint,null);
perform pg_temp.chat_assert(jsonb_array_length(before_page->'messages')=35,'continue backwards without a gap');
end$$;
select pg_temp.chat_denied(format('select public.chat_attachment_prepare(%L,''large.zip'',5242881,''application/zip'')',(select id from chat_test_ids where label='group')),'oversized file denied');
select pg_temp.chat_denied(format('select public.chat_attachment_prepare(%L,''../secret.txt'',10,''text/plain'')',(select id from chat_test_ids where label='group')),'path traversal denied');
insert into chat_test_ids select 'attachment',(public.chat_attachment_prepare((select id from chat_test_ids where label='group'),'notes.txt',10,'text/plain')->>'id')::uuid;
reset role;
set local role authenticated;
insert into storage.objects(bucket_id,name,metadata)select 'chat-attachments',(select company_id::text from public.profiles where id=auth.uid())||'/'||auth.uid()::text||'/'||(select id::text from chat_test_ids where label='group')||'/'||(select id::text from chat_test_ids where label='attachment'),jsonb_build_object('size',10,'mimetype','text/plain');
reset role;
select set_config('request.jwt.claim.sub',(select id::text from chat_test_ids where label='bob'),true);
set local role authenticated;
select pg_temp.chat_assert((select count(*)from storage.objects where bucket_id='chat-attachments'and name like '%/'||(select id::text from chat_test_ids where label='attachment'))=0,'unsent attachment hidden from other participant');
reset role;
select set_config('request.jwt.claim.sub',(select id::text from chat_test_ids where label='alice'),true);
set local role authenticated;
insert into chat_test_ids values('sent',gen_random_uuid());
select public.chat_send_files((select id from chat_test_ids where label='group'),(select id from chat_test_ids where label='sent'),'Attached notes',null,'{}',null,(select array[id]from chat_test_ids where label='attachment'));
select public.chat_send_files((select id from chat_test_ids where label='group'),(select id from chat_test_ids where label='sent'),'Attached notes',null,'{}',null,(select array[id]from chat_test_ids where label='attachment'));
select pg_temp.chat_assert(jsonb_array_length(public.chat_detail((select id from chat_test_ids where label='group'),null,null)->'messages'->-1->'attachments')=1,'attachment linked once on retry');
reset role;
select set_config('request.jwt.claim.sub',(select id::text from chat_test_ids where label='bob'),true);
set local role authenticated;
select pg_temp.chat_assert((select count(*)from storage.objects where bucket_id='chat-attachments'and name like '%/'||(select id::text from chat_test_ids where label='attachment'))=1,'participant can read sent attachment');
reset role;
select set_config('request.jwt.claim.sub',(select id::text from chat_test_ids where label='outsider'),true);
set local role authenticated;
select pg_temp.chat_assert((select count(*)from storage.objects where bucket_id='chat-attachments'and name like '%/'||(select id::text from chat_test_ids where label='attachment'))=0,'other company cannot read attachment');
select pg_temp.chat_denied(format('select public.chat_after(%L,0)',(select id from chat_test_ids where label='group')),'other company cannot page chat');
reset role;
select set_config('request.jwt.claim.sub',(select id::text from chat_test_ids where label='alice'),true);
set local role authenticated;
insert into chat_test_ids values('task',gen_random_uuid());
select public.myday_save_task((select id from chat_test_ids where label='task'),jsonb_build_object('title','QA recurring task','details','Fictional task','due_date',(current_date+1)::text,'status','in_progress','priority','normal','repeat',jsonb_build_object('frequency','weekly','every_n',1,'unit','day')),true);
select pg_temp.chat_assert((select status='in_progress'and repeat_rule->>'frequency'='weekly'from public.actions where id=(select id from chat_test_ids where label='task')),'status and recurrence saved together');
select public.myday_save_task((select id from chat_test_ids where label='task'),jsonb_build_object('title','QA recurring task','details','Fictional task','due_date',(current_date+1)::text,'status','in_progress','repeat',jsonb_build_object('frequency','weekly','every_n',1,'unit','day')),true);
select pg_temp.chat_assert((select count(*)from public.actions where id=(select id from chat_test_ids where label='task'))=1,'task retry does not duplicate');
insert into chat_test_ids values('invalid-task',gen_random_uuid());
select pg_temp.chat_denied(format('select public.myday_save_task(%L,%L::jsonb,true)',(select id from chat_test_ids where label='invalid-task'),jsonb_build_object('title','Invalid recurring task','details','','due_date',(current_date+1)::text,'status','done','repeat',jsonb_build_object('frequency','weekly','every_n',1,'unit','day'))::text),'invalid recurrence rolls back task');
select pg_temp.chat_assert((select count(*)from public.actions where id=(select id from chat_test_ids where label='invalid-task'))=0,'failed recurring save leaves no partial task');
reset role;
set local role authenticated;
insert into storage.objects(bucket_id,name,metadata)select 'member-avatars',company_id::text||'/'||id::text||'/qa-photo.jpg','{"size":12000,"mimetype":"image/jpeg"}'::jsonb from public.profiles where id=(select id from chat_test_ids where label='alice');
set local role authenticated;
select pg_temp.chat_assert(public.member_profile(jsonb_build_object('avatar_path',(select company_id::text||'/'||id::text||'/qa-photo.jpg'from public.profiles where id=(select id from chat_test_ids where label='alice'))))->>'avatar_path' like '%/qa-photo.jpg','compressed profile photo saved');
do $$declare role_id uuid;item_id uuid;value jsonb;begin
role_id:=(public.role_workspace('get',null,'{}')->'role'->>'id')::uuid;
value:=public.role_workspace('save',role_id,jsonb_build_object('id',null,'kind','responsibility','title','Coordinate weekly supplier deliveries','fields',jsonb_build_object('details','Confirm delivery schedules and follow up on changes.','recurrence','Weekly'),'version',1,'include_in_handover',true,'is_private',false,'do_not_change',false,'linked_decision',''));
item_id:=(value->>'id')::uuid;
perform pg_temp.chat_assert(exists(select 1 from public.role_items where id=item_id and title='Coordinate weekly supplier deliveries' and recurrence='Weekly'),'accepted AI work saved through existing role permissions');
end$$;
reset role;

set local role authenticated;
select pg_temp.chat_assert(not has_function_privilege('authenticated','private.require_hr_admin()','execute'),'internal admin helper remains uncallable');
insert into storage.objects(bucket_id,name,metadata)select 'company-logos',company_id::text||'/qa-logo.jpg','{"size":12000,"mimetype":"image/jpeg"}'::jsonb from public.profiles where id=auth.uid();
delete from storage.objects where bucket_id='company-logos'and name like '%/qa-logo.jpg';
select pg_temp.chat_assert(not exists(select 1 from storage.objects where bucket_id='company-logos'and name like '%/qa-logo.jpg'),'admin can upload and remove own company logo');
reset role;
select set_config('request.jwt.claim.sub',(select id::text from chat_test_ids where label='bob'),true);
set local role authenticated;
insert into storage.objects(bucket_id,name,metadata)select 'member-avatars',company_id::text||'/'||id::text||'/qa-employee.jpg','{"size":12000,"mimetype":"image/jpeg"}'::jsonb from public.profiles where id=auth.uid();
select pg_temp.chat_assert(exists(select 1 from storage.objects where bucket_id='member-avatars'and name like '%/qa-employee.jpg'),'employee avatar upload uses authenticated storage policy');
select pg_temp.chat_denied(format('insert into storage.objects(bucket_id,name)values(''company-logos'',%L)',(select company_id::text||'/employee-logo.jpg'from public.profiles where id=auth.uid())),'employee cannot upload company logo');
select pg_temp.chat_denied(format('insert into storage.objects(bucket_id,name)values(''member-avatars'',%L)',(select company_id::text||'/'||id::text||'/other-person.jpg'from public.profiles where id=(select id from chat_test_ids where label='alice'))),'employee cannot replace another avatar');
delete from storage.objects where bucket_id='member-avatars'and name like '%/qa-employee.jpg';
select pg_temp.chat_assert(not exists(select 1 from storage.objects where bucket_id='member-avatars'and name like '%/qa-employee.jpg'),'employee can discard own photo');
reset role;
select count(*) as passed_checks from chat_test_results;

rollback;
